 * Aiming for maximum branch and line coverage.
 */
public class BooleanUtils_toBoolean_TriageGen2Test {





    @Test
    public void testToBoolean_YesVariations() {
        // Case 3: 'y' variations
        assertTrue(BooleanUtils.toBoolean("yes"));
        assertTrue(BooleanUtils.toBoolean("yeS"));
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("YEs"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("YEs"));

        // Case 3: Negative variations
        assertFalse(BooleanUtils.toBoolean("yea"));
        assertFalse(BooleanUtils.toBoolean("yee"));
        assertFalse(BooleanUtils.toBoolean("Yen"));
        assertFalse(BooleanUtils.toBoolean("YEs")); // Correct
        assertFalse(BooleanUtils.toBoolean("Yeb"));
    }








}

